// Build context per lead: normalize sessionKey + extraer fields
const row = $input.first().json;
const fields = row.fields || row;

// Normalización idéntica a normalize_phone() del script Python:
// strip non-digits, validar longitud 10-15
const rawPhone = (fields.Telefono || '').toString();
const cleaned = rawPhone.replace(/[^0-9]/g, '');
const phoneValid = cleaned.length >= 10 && cleaned.length <= 15;

return [{
  json: {
    session_key: phoneValid ? cleaned : null,
    skip_reason: phoneValid ? null : 'phone_invalid',
    lead_fields: fields,
    airtable_id: row.id || null,
    toques_enviados: Number(fields['Toques enviados'] || 0),
    outreach_at_iso: fields['Outreach Form Meta enviado at'] || null,
  }
}];

// Build messages array — 2 a 4 items por lead
// Inputs:
//   - $('Build Context').first().json — { session_key, lead_fields, toques_enviados, outreach_at_iso }
//   - $('Postgres: Check Session Exists').first().json — { row_count } (ya validado = 0)
//
// Output: array de items, cada uno con { session_id, message_json, created_at_iso }

const ctx = $('Build Context').first().json;
const fields = ctx.lead_fields;
const sessionKey = ctx.session_key;
const toques = ctx.toques_enviados;

// === Texto canónico de templates (debe matchear template-texts-canonical.md) ===

const TOUCH_1_TEXT = `Hola {{first_name}}, gracias por tu interés en nuestros programas de Boarding School.

Vimos que recientemente solicitaste información sobre opciones de estudio en el extranjero.

Me gustaría conocer un poco más sobre tu interés para poder orientarte mejor. ¿El programa sería para tu hijo(a) o para algún familiar?`;

const TOUCH_2_TEXT = `Hola {{first_name}},

Muchos padres nos contactan porque quieren brindarles a sus hijos una experiencia internacional que los ayude a desarrollar independencia, confianza y una visión global para su futuro.

Cada estudiante tiene objetivos distintos, por eso nos gustaría entender mejor tu caso para orientarte adecuadamente.

¿Para qué edad o grado escolar estás buscando opciones?`;

const TOUCH_3_TEXT = `Hola {{first_name}},

Sabemos que elegir una experiencia educativa internacional es una decisión importante y que normalmente surgen muchas preguntas sobre destinos, seguridad, costos, requisitos y beneficios para el futuro del estudiante.

Nuestro objetivo es ayudarte a encontrar la mejor opción según las metas y necesidades de tu familia.

Si aún estás explorando alternativas, responde este mensaje y con gusto te orientaremos sin compromiso.`;

// === Helpers ===

function buildSystemMessage(d) {
  const nombre = (d.Nombre || '').toString().trim();
  const apellido = (d.Apellido || '').toString().trim();
  const nombreCompleto = (d['Nombre Completo'] || [nombre, apellido].filter(Boolean).join(' ').trim()) || 'el lead';

  const email = d.Email ? d.Email : null;
  const tel = d.Telefono ? `tel +${d.Telefono}` : null;
  const contact = [email, tel].filter(Boolean).join(', ');
  const contactStr = contact ? ` (${contact})` : '';

  const origenMap = {
    'Form Meta': 'completó un formulario de Meta',
    'Form Landing': 'completó el formulario de nuestra landing',
    'CTWA': 'vino por un anuncio de WhatsApp',
  };
  const accion = origenMap[d.Origen] || 'mostró interés';

  const programa = d['Programa interés']
    ? ` interesado/a en ${d['Programa interés']}`
    : ' interesado/a en uno de nuestros programas';

  const cualif = [
    d['Grado Escolar'] && `para ${d['Grado Escolar']}`,
    d['Inicio Deseado'] && `con inicio deseado en ${d['Inicio Deseado']}`,
    d['Nivel Inglés'] && `y nivel de inglés ${d['Nivel Inglés']}`,
  ].filter(Boolean).join(' ');
  const cualifStr = cualif ? ` ${cualif}` : '';

  const campania = d['Ad Name']
    ? ` Vino por la campaña ${d['Ad Name']}${d.Platform ? ' en ' + d.Platform : ''}.`
    : '';

  return `El lead ${nombreCompleto}${contactStr} ${accion}${programa}${cualifStr}.${campania}`;
}

function renderTemplate(tpl, firstName) {
  const fn = (firstName || '').toString().trim() || 'hola';
  return tpl.replace(/\{\{first_name\}\}/g, fn);
}

// === Timestamps ===

const baseAtRaw = ctx.outreach_at_iso;
let baseAt;
if (baseAtRaw) {
  baseAt = new Date(baseAtRaw);
} else {
  baseAt = new Date(Date.now() - 24 * 60 * 60 * 1000); // fallback: -24h
}
if (isNaN(baseAt.getTime())) {
  baseAt = new Date(Date.now() - 24 * 60 * 60 * 1000);
}
const systemAt = new Date(baseAt.getTime() - 1000); // 1s antes del Touch 1 para que quede ordenado primero

// === Build mensajes ===

const systemText = buildSystemMessage(fields);
const firstName = (fields.Nombre || '').toString();

const messages = [
  { session_id: sessionKey, type: 'system', content: systemText, created_at: systemAt.toISOString() },
  { session_id: sessionKey, type: 'ai', content: renderTemplate(TOUCH_1_TEXT, firstName), created_at: baseAt.toISOString() },
];

if (toques >= 2) {
  const t2 = new Date(baseAt.getTime() + 24 * 60 * 60 * 1000);
  messages.push({ session_id: sessionKey, type: 'ai', content: renderTemplate(TOUCH_2_TEXT, firstName), created_at: t2.toISOString() });
}

if (toques >= 3) {
  const t3 = new Date(baseAt.getTime() + 72 * 60 * 60 * 1000);
  messages.push({ session_id: sessionKey, type: 'ai', content: renderTemplate(TOUCH_3_TEXT, firstName), created_at: t3.toISOString() });
}

// Devolver 1 item por mensaje (el Postgres node insertará N veces)
return messages.map(m => ({ json: {
  session_id: m.session_id,
  message_json: JSON.stringify({ type: m.type, content: m.content }),
  created_at: m.created_at,
}}));

